template <typename T>
T maximum(T a, T b) {
    return (a > b) ? a : b;
}

// Template usage (Instantiation)
int max_i = maximum(10, 20);
double max_d = maximum(3.5, 1.2);

// Template with Non-Type Parameter
template <typename T, int N>
T array_sum(T (&arr)[N]) {
    T sum = 0;
    for (int i=0; i < N; ++i) {
        sum += arr[i];
    }
    return sum;
}

int data[] = {1, 2, 3};
int result = array_sum(data);

// Explicit Specification
int max_e = maximum<int>(5, 3);
